import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Build CUDA extension with a single fused kernel for GELU
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>
__global__ void gelu_fused_kernel(const float* __restrict__ x, float* __restrict__ y, long long N) {
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;
    const float k = 0.7978845608028654f; // sqrt(2.0 / pi)
    // Vectorized path: process float4 chunks
    long long N4 = N >> 2; // number of float4 elements
    const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x);
    float4* __restrict__ y4 = reinterpret_cast<float4*>(y);
    for (long long i4 = idx; i4 < N4; i4 += stride) {
        float4 xv = x4[i4];
        float v0 = xv.x; float v1 = xv.y; float v2 = xv.z; float v3 = xv.w;
        float4 yv;
        yv.x = 0.5f * v0 * (1.0f + __tanhf(k * fmaf(0.044715f, v0 * v0 * v0, v0)));
        yv.y = 0.5f * v1 * (1.0f + __tanhf(k * fmaf(0.044715f, v1 * v1 * v1, v1)));
        yv.z = 0.5f * v2 * (1.0f + __tanhf(k * fmaf(0.044715f, v2 * v2 * v2, v2)));
        yv.w = 0.5f * v3 * (1.0f + __tanhf(k * fmaf(0.044715f, v3 * v3 * v3, v3)));
        y4[i4] = yv;
    }
    // Tail handling for remaining elements
    long long start = N4 << 2; // 4 * N4
    for (long long i = start + idx; i < N; i += stride) {
        float v = x[i];
        y[i] = 0.5f * v * (1.0f + __tanhf(k * fmaf(0.044715f, v * v * v, v)));
    }
}
at::Tensor gelu_forward(const at::Tensor& x) {
    TORCH_CHECK(x.is_cuda(), "gelu_forward: input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "gelu_forward: input must be float32");
    auto x_contig = x.contiguous();
    auto y = at::empty_like(x_contig);
    long long N = x_contig.numel();
    int threads = 512;
    long long vec_elems = N / 4;
    long long work = vec_elems > 0 ? vec_elems : N;
    long long blocks_ll = (work + threads - 1) / threads;
    int blocks = (int)std::min<long long>(blocks_ll > 0 ? blocks_ll : 1LL, 65535LL);
    auto stream = at::cuda::getCurrentCUDAStream();
    gelu_fused_kernel<<<blocks, threads, 0, stream>>>(
        x_contig.data_ptr<float>(),
        y.data_ptr<float>(),
        N
    );
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "gelu_fused_kernel launch failed: ", cudaGetErrorString(err));
    return y.view(x.sizes());
}
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_forward", &gelu_forward, "Fused GELU forward (CUDA)");
}
"""

_ext = load_inline(
    name="fused_gelu_ext",
    cpp_sources=[],
    cuda_sources=[_cuda_src],
    with_cuda=True,
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        orig_device = x.device
        if orig_device.type != "cuda":
            x = x.to("cuda")
        if x.dtype != torch.float32:
            x = x.float()
        y = _ext.gelu_forward(x)
        if orig_device.type != "cuda":
            y = y.to(orig_device)
        return y

